<?php
require_once __DIR__.'/address.php';
final class PDSPaperDocument {
    public static function text($value): string {
        if (is_array($value)) return implode(', ', array_map([self::class,'text'], $value));
        $value=trim((string)($value??''));
        if ($value!=='' && ($value[0]==='[' || $value[0]==='{')) { $decoded=json_decode($value,true);if(is_array($decoded)&&($decoded['pds_addresses']??null)===1)return PDSAddress::display($value);if(is_array($decoded))return self::text($decoded); }
        return $value;
    }
    public static function e($value): string { return htmlspecialchars(self::text($value),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
    private static function normal($value): string { return mb_strtolower(trim(preg_replace('/\s+/u',' ',str_replace(['_','-'], ' ', self::text($value))))); }
    public static function choices($value,array $options,bool $showRecorded=true): string {
        $raw=self::text($value);$pieces=array_map([self::class,'normal'],preg_split('/[,;|]+/u',$raw));$tokens=array_merge([self::normal($raw)],$pieces);$html='';$matched=[];$exact=false;
        foreach($options as $label=>$aliases){$checked=false;foreach((array)$aliases as $alias){$normalized=self::normal($alias);if(in_array($normalized,$tokens,true)){$checked=true;$matched[]=$normalized;if($normalized===self::normal($raw))$exact=true;}}$html.='<span class="pds-option"><span class="pds-tick" aria-hidden="true">'.($checked?'×':'').'</span>'.self::e($label).'</span>';}
        if($raw!==''&&!$exact&&array_diff($pieces,$matched)&&$showRecorded)$html.='<span class="pds-recorded">Recorded: '.self::e($raw).'</span>';
        return $html;
    }
    public static function line(string $label,$value,string $class=''): string { return '<span class="pds-field '.self::e($class).'"><span class="pds-field-label">'.self::e($label).'</span><span class="pds-write">'.(self::text($value)!==''?self::e($value):'&nbsp;').'</span></span>'; }
    public static function date($value): string { $value=self::text($value);if($value===''||$value==='0000-00-00')return ''; $stamp=strtotime($value);return $stamp===false?$value:date('m/d/Y',$stamp); }
    public static function baseUrl(): string { $path=str_replace('\\','/',$_SERVER['SCRIPT_NAME']??'');foreach(['/dashboard/','/pds/'] as $marker){$at=strpos($path,$marker);if($at!==false)return substr($path,0,$at).'/';}return '/'.basename(dirname(__DIR__,2)).'/'; }
    public static function media($value,string $base,string $kind='photo'): string {
        $value=self::text($value);if($value==='')return '';
        if($kind==='signature')return $base.'pds/signature.php?key='.hash('sha256',$value);
        if(strlen($value)<7000000&&preg_match('~^data:image/(?:png|jpeg|gif|webp);base64,[a-zA-Z0-9+/=\r\n]+$~D',$value))return $value;
        return $base.'pds/photo.php?key='.hash('sha256',$value);
    }
    private static function typedSignature($value): string {
        $value=self::text($value);
        if(strlen($value)>200||preg_match('~(?:^data:|://|[/\\\\]|\.(?:png|jpe?g|gif|webp)$)~i',$value))return '';
        return self::e($value);
    }
    private static function siblingCounts(array $data): string {
        $html='<div class="pds-sibling-counts">';$hasCounts=false;
        foreach(['brothers_count'=>'Brother/s','sisters_count'=>'Sister/s','stepbrothers_count'=>'Step brother/s','stepsisters_count'=>'Step sister/s','adopted_count'=>'Adopted'] as $field=>$label){if(isset($data[$field])&&$data[$field]!=='')$hasCounts=true;$html.=self::line($label.':',$data[$field]??'');}
        $html.='</div>';if(!$hasCounts&&!empty($data['sibling_type']))$html.='<div class="pds-recorded">Recorded sibling types: '.self::e($data['sibling_type']).'</div>';return $html;
    }
    private static function parentCell(array $data,string $parent,string $part): string {
        $get=static fn($key)=>self::text($data[$parent.'_'.$key]??'');$line=[self::class,'line'];$options=[self::class,'choices'];
        if($part==='name'){$name=implode(', ',array_filter([$get('surname'),$get('given_name'),$get('middle_name')],static fn($v)=>$v!==''));if(in_array(self::normal($get('type')),['deceased','dead'],true)||self::normal($get('status'))==='deceased')$name='+ '.$name;return '<strong>'.ucfirst($parent).'’s Name:</strong><small>Surname &nbsp; Given name &nbsp; Middle name</small><div class="pds-name-space">'.self::e($name).'</div>';}
        if($part==='occupation')return $line('Occupation:',$get('occupation')).($get('contact')!==''?$line('Contact:',$get('contact')):'');
        if($part==='location')return '<div class="pds-parent-halves"><div>Location:<br>'.$options($get('location'),['Overseas'=>['Overseas','Abroad','OFW'],'Local'=>'Local']).'</div><div>Type:<br>'.$options($get('type'),['Private'=>'Private','Govt.'=>['Government','Govt','Govt.']]).'</div></div>';
        if($part==='status')return 'Status: '.$options($get('status'),['Employed'=>'Employed','Unemployed'=>'Unemployed','Deceased'=>'Deceased','Retired'=>'Retired','Disabled'=>'Disabled']);
        if($part==='education')return '<strong>Highest Educational Attainment:</strong><div class="pds-parent-halves pds-education-choices"><div>'.$options($get('education'),['Some Elementary'=>'Some Elementary','Elementary'=>'Elementary','Some High School'=>'Some High School','High School'=>'High School','Some College'=>'Some College'],false).'</div><div>'.$options($get('education'),['College / Degree'=>['College','College Graduate','College Degree'],'Postgraduate studies'=>['Post Graduate','Postgraduate','Postgraduate studies']],false).$line('Degree:',$get('degree')).'<div>'.$options($get('postgrad'),['MA/MS'=>['MA','MS','MA/MS','MS/MS'],'PhD'=>['PhD','Ph.D.']]).'</div>'.$line('Specialization:',$get('specialization')).'</div></div>'.$line('Others pls. specify:',in_array(self::normal($get('education')),['','some elementary','elementary','some high school','high school','some college','college','college graduate','college degree','postgraduate studies','post graduate','postgraduate'],true)?'':$get('education'));
        return '';
    }
